  `cantidad_disponible` int(11) DEFAULT 1,
  `cantidad_prestada` int(11) DEFAULT 0,
  `proveedor_id` int(11) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

